#include <iostream>
#include <string>
#include <fstream>
using namespace std;

class InvalidDataException {
public:
    void displayError() const { cout << "Error: Negative values not allowed." << endl; }
};

template <typename T>
T calculateTax(T cost) { return cost * 0.05; }

class Person {
protected:
    string name; int age;
public:
    Person(string n = "Unknown", int a = 0) : name(n), age(a) {}
    virtual ~Person() {}
};

class Patient : public Person {
private:
    int patientID; string condition; double treatmentCost;
    static int nextID;
public:
    Patient(string n, int a, string cond) : Person(n, a) {
        if (a < 0) throw InvalidDataException();
        patientID = nextID++; condition = cond; treatmentCost = 0.0;
    }
    virtual ~Patient() {}
    Patient& operator+(double amount) {
        if (amount < 0) throw InvalidDataException();
        treatmentCost += amount; return *this;
    }
    virtual void triage() = 0;
    friend class BillingSystem;
};
int Patient::nextID = 1001;
